<script setup lang="ts">
import type {PayBreakdown} from '../payrollTypes'
import {usePayrollText} from '../payrollText'
import {incomeFields,deductionFields,employerFields,groupItems} from '../payBreakdown'
defineProps<{value:PayBreakdown;details?:boolean;aggregated?:boolean}>()
const {r}=usePayrollText()
const groups=[{name:'incomeGroup',kind:'income',fields:incomeFields},{name:'deductionGroup',kind:'deductions',fields:deductionFields},{name:'employerGroup',kind:'employer',fields:employerFields}] as const
function label(field:string){return r(({basic:'basicPay',overtime:'overtimePay',employerCharges:'employerBorne'} as Record<string,string>)[field] as Parameters<typeof r>[0]||field as Parameters<typeof r>[0])}
</script>
<template><div class="wf-pay-groups"><section v-for="group in groups" :key="group.kind"><h3>{{r(group.name)}}</h3><dl><template v-for="field in group.fields" :key="field"><dt>{{label(field)}}</dt><dd>{{field==='sdl'?value[field].replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,''):value[field]}}</dd></template></dl><details open v-if="details&&groupItems(value.items,group.kind).length"><summary>{{r('itemLabel')}}</summary><dl><template v-for="(item,i) in groupItems(value.items,group.kind)" :key="i"><dt>{{item.kind==='basic'?r('basicPay'):item.kind==='overtime'?r('overtimePay'):item.label}}</dt><dd>{{item.amount}}</dd></template></dl></details></section></div><p class="wf-hint">{{r('reimbursementGroup')}}: {{value.reimbursements}}</p><dl v-if="details&&groupItems(value.items,'reimbursements').length" class="wf-details"><template v-for="(item,i) in groupItems(value.items,'reimbursements')" :key="i"><dt>{{item.label}}</dt><dd>{{item.amount}}</dd></template></dl><div class="wf-pay-final"><strong>{{r('gross')}} {{value.gross}}</strong><strong>{{r('net')}} SGD {{value.net}}</strong><span v-if="value.employerCost">{{r(aggregated?'employerCost':'employeeCostEstimate')}} {{value.employerCost}}</span></div></template>
<style scoped>.wf-pay-groups{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.wf-pay-groups section{border:1px solid #dbe4ee;border-radius:8px;padding:12px}.wf-pay-groups h3{margin:0 0 10px}.wf-pay-groups dl{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px;margin:0}.wf-pay-groups dd{margin:0;text-align:right;font-variant-numeric:tabular-nums}.wf-pay-groups dt{overflow-wrap:anywhere}.wf-pay-groups details{margin-top:10px}.wf-pay-final{display:flex;gap:20px;flex-wrap:wrap;border-top:1px solid #dbe4ee;padding:12px 0}@media(max-width:650px){.wf-pay-groups{grid-template-columns:1fr}}@media print{.wf-pay-groups details{display:block}.wf-pay-groups{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>
